function UICultivateEquipHeadNode:RefreshUI(equipDojo, part, isActiveedCore, coreSuitId, isDisableEffect)
    local isOwnEquip = equipDojo ~= nil
    KTool.SetActive(self.Empty.gameObject, not isOwnEquip)
    KTool.SetActive(self.TarotGroup.gameObject, isOwnEquip)

    local quality
    local isActiveEquip = false
    if isOwnEquip then
        local refId = equipDojo.equipmentId
        ---@type GoodsVo
        local goodsVo = goodsConfMgr:GetGoodsVoById(equipDojo.equipmentId)
        self.ImgEquipIcon:LoadSprite(goodsVo.photoPath)

        ---@type EquipVo
        local equipVo = cardConfMgr:GetEquipVoById(refId)
        local suitId  = equipVo.suitId
        isActiveEquip = isActiveedCore == true and coreSuitId == suitId
        quality = goodsVo.quality
        self.ImgBg.Status = quality

        EquipUtils.SetEquipPartBgScale(self.QualityContainer.transform, part)

    else
        EquipUtils.SetEquipPartBgScale(self.Empty.transform, part)
    end

    self:PlayAllEffect(isActiveEquip, quality, isDisableEffect)

    return isActiveEquip
end


function UICultivateEquipHeadNode:StopEffectCo(effectType)
    local co = self.effectCos[effectType]
    if co then
        cs_coroutine.stop(co)
        self.effectCos[effectType] = nil
    end
end
function UICultivateEquipHeadNode:PlayEquipEffect(effectType, rare)
    self:StopEffectCo(effectType)
    local co = cs_coroutine.start(function()
        xTry(function()
            local go = self.effectGos[effectType]
            if go == nil then
                go = GameUtils.LoadBundleAsync(EffectConfig[effectType], self.QualityContainer.gameObject, nil, true)
                self.effectGos[effectType] = go
                self.effectUiSwitch[effectType] = go.gameObject:GetComponentsInChildren(UISwitchParticleSystemType)
            end

            local uiSwiComps = self.effectUiSwitch[effectType]
            for i = 1, uiSwiComps.Length do
                uiSwiComps[i - 1].Status = checkNumber(rare)
            end
            if EffectType.Active == effectType then
                KTool.SetActive(go.gameObject, true)
                cs_coroutine.yield_return(Yielders.GetWaitForSeconds(2))
                KTool.SetActive(go.gameObject, false)
            else
                KTool.SetActive(go.gameObject, false)
                cs_coroutine.yield_return()
                KTool.SetActive(go.gameObject, true)
            end
            self.effectCos[effectType] = nil

        end)
    end)

    self.effectCos[effectType] = co
end

function UICultivateEquipHeadNode:PlayAllEffect(isActiveEquip, quality, isDisableEffect)
    if isActiveEquip then
        if not isDisableEffect then
            self:PlayEquipEffect(EffectType.Active, quality)
        end
        self:PlayEquipEffect(EffectType.Loop, quality)
    else
        self:HideEffect(EffectType.Active)
        self:HideEffect(EffectType.Loop)
    end
end

function UICultivateEquipHeadNode:HideEffect(effectType)
    self:StopEffectCo(effectType)
    local go = self.effectGos[effectType]
    if go then
        KTool.SetActive(go.gameObject, false)
    end
end

